package executionapp

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"time"

	auditapp "github.com/EdouardRichard/EzTest/backend/internal/audit/application"
	execution "github.com/EdouardRichard/EzTest/backend/internal/execution/domain"
	"github.com/EdouardRichard/EzTest/backend/internal/platform"
	platformid "github.com/EdouardRichard/EzTest/backend/internal/platform/id"
)

// IntentService creates and cancels execution intents. The automatic initial
// intents are generated by the reconciler; retest/manual intents are created by
// the API (P3 §5.1/§5.8).
type IntentService struct {
	intents  IntentRepository
	cases    CaseReader
	versions VersionReader
	batches  BatchSelectionReader
	ids      IDGenerator
	clock    Clock
	events   EventPublisher
	audit    AuditRecorder
}

// IntentServiceDeps wires the intent service.
type IntentServiceDeps struct {
	Intents  IntentRepository
	Cases    CaseReader
	Versions VersionReader
	// BatchSelections projects the execute.batch selection persisted on the
	// stage-entry work item. It scopes the startup/leader repair scan (D23); nil
	// degrades to the typed skip, never to an unscoped scan.
	BatchSelections BatchSelectionReader
	IDs             IDGenerator
	Clock           Clock
	Events          EventPublisher
	Audit           AuditRecorder
}

// NewIntentService builds the intent service.
func NewIntentService(deps IntentServiceDeps) *IntentService {
	return &IntentService{
		intents:  deps.Intents,
		cases:    deps.Cases,
		versions: deps.Versions,
		batches:  deps.BatchSelections,
		ids:      deps.IDs,
		clock:    deps.Clock,
		events:   deps.Events,
		audit:    deps.Audit,
	}
}

// Initial execution intents only belong to the executing stage (Task 78): a
// case version that was merely confirmed at the case hard gate is not yet
// executable, and confirming it must never auto-create a wave. A completed
// version keeps the P3 §5.9 reopen-on-environment-change semantics.
const (
	intentExecutableStage = "executing"
	intentCompletedStage  = "completed"
)

// EnsureInitialIntents is the startup/leader repair scan (P3 §5.1/§5.7). It
// refreshes initial intents only for the case selection frozen by the
// execute.batch stage-entry job (D23): after a restart or a leader failover,
// previously confirmed but unselected cases must not silently enter a wave. ids
// are unique on (case_version, fingerprint, baseline, purpose=initial), so a
// repeated scan, confirmation or API restart never duplicates an intent
// (P3-D-08). A completed version is reopened first (P3 §5.9), again within the
// persisted selection.
//
// The scan is stage-gated: before the case hard gate (case_review and earlier)
// a confirmed case is not executable yet, so the scan returns without creating
// intents and no wave can be planned. When the version has no persisted
// execute.batch selection (the stage-entry job was never enqueued, e.g. the
// dispatch crashed before the work item was written), the scan returns
// ErrNoPersistedBatchSelection and creates nothing: R49 stage-entry recovery
// re-enqueues the scoped execute.batch job, which performs the explicit
// selection refresh instead. An empty persisted selection keeps its contract
// meaning ("all current confirmed cases").
func (s *IntentService) EnsureInitialIntents(ctx context.Context, versionID int64) (int, error) {
	return s.ensureInitialIntents(ctx, versionID, nil, false, true)
}

// EnsureInitialIntentsForCases is the explicit execute.batch refresh: it creates
// initial intents only for the selected case IDs (D23) and requires the version
// to be at executing. A selection naming a case that is not current+confirmed
// is a typed 409: the caller must not silently run a different/larger batch.
func (s *IntentService) EnsureInitialIntentsForCases(ctx context.Context, versionID int64, caseIDs []int64) (int, error) {
	selection, err := normalizeIntentCaseSelection(caseIDs)
	if err != nil {
		return 0, err
	}
	return s.ensureInitialIntents(ctx, versionID, selection, true, false)
}

// normalizeIntentCaseSelection deduplicates the selected case IDs. A nil/empty
// list keeps the D23 "all current draft cases" meaning and is passed through.
func normalizeIntentCaseSelection(caseIDs []int64) (map[int64]struct{}, error) {
	if len(caseIDs) == 0 {
		return nil, nil
	}
	selection := make(map[int64]struct{}, len(caseIDs))
	for _, caseID := range caseIDs {
		if caseID <= 0 {
			return nil, platform.Invalid("case_ids", "must contain positive decimal IDs")
		}
		selection[caseID] = struct{}{}
	}
	return selection, nil
}

// persistedBatchSelection reads the execute.batch case_ids frozen on the
// stage-entry work item. A nil reader (degraded assembly) is the same typed skip
// as a missing row: the repair scan must never widen to every confirmed case.
// A repository failure is real and is surfaced instead of silently skipping.
func (s *IntentService) persistedBatchSelection(ctx context.Context, versionID int64) ([]int64, bool, error) {
	if s.batches == nil {
		return nil, false, nil
	}
	caseIDs, found, err := s.batches.ExecuteBatchSelection(ctx, versionID)
	if err != nil {
		return nil, false, mapExecutionError(err, "execute batch selection")
	}
	return caseIDs, found, nil
}

// ensureInitialIntents is the shared scan. selection != nil narrows it to the
// selected case IDs; explicit marks the execute.batch path, where a version at
// the wrong stage must be a typed 409 instead of a silent no-op; repair scopes
// the startup/leader scan to the persisted execute.batch selection.
func (s *IntentService) ensureInitialIntents(
	ctx context.Context,
	versionID int64,
	selection map[int64]struct{},
	explicit bool,
	repair bool,
) (int, error) {
	if err := requirePositiveID("version_id", versionID); err != nil {
		return 0, err
	}
	binding, err := s.versions.Get(ctx, versionID)
	if err != nil {
		return 0, mapExecutionError(err, "version")
	}
	executableStage := binding.Stage == intentExecutableStage ||
		(!explicit && binding.Stage == intentCompletedStage)
	if !executableStage {
		if explicit {
			return 0, invalidStageForExecution(binding.Stage)
		}
		return 0, nil
	}
	if repair {
		persisted, found, err := s.persistedBatchSelection(ctx, versionID)
		if err != nil {
			return 0, err
		}
		if !found {
			// Typed skip: never fall back to every confirmed case. The R49
			// stage-entry recovery re-enqueues the scoped execute.batch job.
			return 0, fmt.Errorf("%w: version %d", ErrNoPersistedBatchSelection, versionID)
		}
		if selection, err = normalizeIntentCaseSelection(persisted); err != nil {
			return 0, err
		}
	}
	cases, err := s.cases.ListExecutable(ctx, versionID)
	if err != nil {
		return 0, mapExecutionError(err, "version")
	}
	if len(cases) == 0 {
		return 0, nil
	}
	if selection != nil {
		available := make(map[int64]struct{}, len(cases))
		for _, snapshot := range cases {
			available[snapshot.CaseID] = struct{}{}
		}
		for caseID := range selection {
			if _, ok := available[caseID]; !ok {
				return 0, &platform.Error{
					Status: http.StatusConflict,
					Code:   "selected_case_not_executable",
					Message: fmt.Sprintf(
						"selected case %d is not a current confirmed case of the version", caseID,
					),
					Details: map[string]any{
						"case_id":     platformid.Format(caseID),
						"next_action": "refresh the design graph, confirm the case at the case gate, then execute the batch again",
					},
				}
			}
		}
		filtered := make([]execution.CaseSnapshot, 0, len(selection))
		for _, snapshot := range cases {
			if _, ok := selection[snapshot.CaseID]; ok {
				filtered = append(filtered, snapshot)
			}
		}
		cases = filtered
	}
	fingerprint, err := EnvironmentFingerprint(binding)
	if err != nil {
		return 0, err
	}
	baseline := CodeBaseline(binding)
	now := s.now()
	reopened := false
	created := 0
	for _, snapshot := range cases {
		existing, err := s.intents.CountInitialFor(ctx, snapshot.CaseVersionID, fingerprint, baseline)
		if err != nil {
			return created, mapExecutionError(err, "intent")
		}
		if existing > 0 {
			continue
		}
		if !reopened && binding.Status == "completed" {
			if err := s.versions.Reopen(ctx, versionID); err != nil {
				return created, mapExecutionError(err, "version")
			}
			binding.Status = "running"
			reopened = true
		}
		intent := execution.ExecutionIntent{
			ID:                     s.ids.Next(),
			VersionID:              versionID,
			CaseVersionID:          snapshot.CaseVersionID,
			VersionSUTIDs:          caseIntentVersionSUTIDs(snapshot),
			EnvironmentFingerprint: fingerprint,
			CodeBaseline:           baseline,
			Purpose:                execution.PurposeInitial,
			Status:                 execution.IntentOpen,
			DedupeKey:              DedupeKey(snapshot.CaseVersionID, fingerprint, baseline, execution.PurposeInitial),
			AttemptNo:              1,
			CreatedAt:              now,
			UpdatedAt:              now,
		}
		if err := intent.Validate(); err != nil {
			return created, platform.Invalid("intent", "could not build a valid execution intent")
		}
		if err := s.createIntent(ctx, intent); err != nil {
			if errors.Is(err, execution.ErrDuplicate) {
				// A concurrent scan created it; the intent is still covered.
				continue
			}
			if errors.Is(err, execution.ErrRequirementClosed) {
				// The requirement was closed before this scan created its
				// initial intent; a closed requirement is terminal, so the
				// scan skips that case instead of failing the whole version.
				continue
			}
			return created, mapExecutionError(err, "intent")
		}
		created++
		s.publishCreated(ctx, intent, 0)
	}
	return created, nil
}

// CreateManual creates an explicit retest/manual intent (P3 §5.8). A duplicate
// active intent for the same natural key is a state_conflict.
func (s *IntentService) CreateManual(ctx context.Context, versionID, caseVersionID int64, purpose execution.Purpose, actorID int64) (execution.ExecutionIntent, error) {
	if err := requirePositiveID("version_id", versionID); err != nil {
		return execution.ExecutionIntent{}, err
	}
	if err := requirePositiveID("case_version_id", caseVersionID); err != nil {
		return execution.ExecutionIntent{}, err
	}
	if purpose != execution.PurposeRetest && purpose != execution.PurposeManual {
		return execution.ExecutionIntent{}, platform.Invalid("purpose", "must be retest or manual")
	}
	binding, err := s.versions.Get(ctx, versionID)
	if err != nil {
		return execution.ExecutionIntent{}, mapExecutionError(err, "version")
	}
	snapshot, err := s.cases.GetCaseVersion(ctx, versionID, caseVersionID)
	if err != nil {
		return execution.ExecutionIntent{}, mapExecutionError(err, "case version")
	}
	fingerprint, err := EnvironmentFingerprint(binding)
	if err != nil {
		return execution.ExecutionIntent{}, err
	}
	baseline := CodeBaseline(binding)
	if binding.Status == "completed" {
		if err := s.versions.Reopen(ctx, versionID); err != nil {
			return execution.ExecutionIntent{}, mapExecutionError(err, "version")
		}
	}
	now := s.now()
	intent := execution.ExecutionIntent{
		ID:                     s.ids.Next(),
		VersionID:              versionID,
		CaseVersionID:          caseVersionID,
		VersionSUTIDs:          caseIntentVersionSUTIDs(snapshot),
		EnvironmentFingerprint: fingerprint,
		CodeBaseline:           baseline,
		Purpose:                purpose,
		Status:                 execution.IntentOpen,
		DedupeKey:              DedupeKey(caseVersionID, fingerprint, baseline, purpose),
		AttemptNo:              1,
		CreatedBy:              actorID,
		CreatedAt:              now,
		UpdatedAt:              now,
	}
	if err := intent.Validate(); err != nil {
		return execution.ExecutionIntent{}, platform.Invalid("intent", "could not build a valid execution intent")
	}
	if err := s.createIntent(ctx, intent); err != nil {
		if errors.Is(err, execution.ErrDuplicate) {
			return execution.ExecutionIntent{}, platform.StateConflict("an active intent already exists for this case, environment and purpose")
		}
		if errors.Is(err, execution.ErrRequirementClosed) {
			return execution.ExecutionIntent{}, platform.StateConflict("the requirement is closed; reopen it before creating an execution intent")
		}
		return execution.ExecutionIntent{}, mapExecutionError(err, "intent")
	}
	s.publishCreated(ctx, intent, actorID)
	return intent, nil
}

// Cancel cancels one intent. Cancelling a terminal intent is idempotent: it
// returns nil so the API can answer 200 with the current state (§5.8).
func (s *IntentService) Cancel(ctx context.Context, intentID, actorID int64) error {
	if err := requirePositiveID("intent_id", intentID); err != nil {
		return err
	}
	intent, err := s.intents.Get(ctx, intentID)
	if err != nil {
		return mapExecutionError(err, "intent")
	}
	if intent.Status.Terminal() {
		return nil
	}
	changed, err := s.intents.Transition(ctx, intentID, activeIntentStatuses, execution.IntentCancelled)
	if err != nil {
		return mapExecutionError(err, "intent")
	}
	if !changed {
		current, err := s.intents.Get(ctx, intentID)
		if err != nil {
			return mapExecutionError(err, "intent")
		}
		if current.Status.Terminal() {
			return nil
		}
		return platform.StateConflict("the intent is not in a cancelable state")
	}
	publishEvent(ctx, s.events, EventIntentCancelled, intent.VersionID,
		map[string]any{"intent_id": platformid.Format(intentID)},
		map[string]any{"intent_id": platformid.Format(intentID), "reason": "cancelled"},
		actorPtr(actorID))
	s.recordAudit(ctx, "execution.intent_cancelled", intent, actorID)
	return nil
}

var activeIntentStatuses = []execution.IntentStatus{execution.IntentOpen, execution.IntentClaimed, execution.IntentRunning}

// intentCreateAttempts bounds the reopen-and-retry loop used when a version
// close wins the shared version advisory lock between the service pre-check and
// the insert.
const intentCreateAttempts = 3

// createIntent inserts an intent through the repository, which serializes with
// version close/requirement closure on the version advisory lock. When a
// concurrent close committed first the repository reports ErrVersionCompleted;
// the service reopens the version through the version port (P4
// version.reopened, trigger=execution_intent) and retries so the final state is
// never a completed version with an active intent. A closed requirement is
// returned as-is: the callers decide between skipping (reconciler) and a state
// conflict (manual API).
func (s *IntentService) createIntent(ctx context.Context, intent execution.ExecutionIntent) error {
	for attempt := 0; attempt < intentCreateAttempts; attempt++ {
		err := s.intents.Create(ctx, intent)
		if err == nil {
			return nil
		}
		if !errors.Is(err, execution.ErrVersionCompleted) {
			return err
		}
		if err := s.versions.Reopen(ctx, intent.VersionID); err != nil {
			return mapExecutionError(err, "version")
		}
	}
	return platform.StateConflict("the version is being closed; retry creating the execution intent")
}

func (s *IntentService) publishCreated(ctx context.Context, intent execution.ExecutionIntent, actorID int64) {
	versionRef := platformid.Format(intent.VersionID)
	publishEvent(ctx, s.events, EventIntentCreated, intent.VersionID,
		map[string]any{
			"intent_id":       platformid.Format(intent.ID),
			"case_version_id": platformid.Format(intent.CaseVersionID),
		},
		map[string]any{
			"intent_id":       platformid.Format(intent.ID),
			"case_version_id": platformid.Format(intent.CaseVersionID),
			"purpose":         string(intent.Purpose),
			"version_sut_ids": idsToStrings(intent.VersionSUTIDs),
			"version_id":      versionRef,
		},
		actorPtr(actorID))
	s.recordAudit(ctx, "execution.intent_created", intent, actorID)
}

func (s *IntentService) recordAudit(ctx context.Context, action string, intent execution.ExecutionIntent, actorID int64) {
	if s.audit == nil {
		return
	}
	var actor *int64
	if actorID > 0 {
		actor = &actorID
	}
	_ = s.audit.Record(ctx, auditapp.Event{
		ActorID:    actor,
		Action:     action,
		TargetKind: "execution_intent",
		TargetID:   platformid.Format(intent.ID),
		Metadata: map[string]any{
			"id":              platformid.Format(intent.ID),
			"case_version_id": platformid.Format(intent.CaseVersionID),
			"purpose":         string(intent.Purpose),
			"status":          string(intent.Status),
		},
	})
}

func (s *IntentService) now() time.Time {
	if s.clock == nil {
		return time.Now().UTC()
	}
	return s.clock.Now()
}

func actorPtr(actorID int64) *int64 {
	if actorID <= 0 {
		return nil
	}
	return &actorID
}

// invalidStageForExecution is the typed 409 returned when the explicit
// execute.batch refresh runs on a version that is not at executing. It carries
// the next action so the caller can guide the user instead of failing silently.
func invalidStageForExecution(current string) error {
	return &platform.Error{
		Status:  http.StatusConflict,
		Code:    "invalid_stage_for_execution",
		Message: fmt.Sprintf("batch execution requires stage executing, but the version is at %s", current),
		Details: map[string]any{
			"required_stage": "executing",
			"current_stage":  current,
			"next_action":    "confirm the selected cases at the case gate and execute the batch again",
		},
	}
}

// caseIntentVersionSUTIDs is the §5.1 intent SUT set: every step's resolved
// target plus the case default, deduplicated and sorted.
func caseIntentVersionSUTIDs(snapshot execution.CaseSnapshot) []int64 {
	ids := make([]int64, 0, len(snapshot.Steps)+1)
	ids = append(ids, snapshot.DefaultVersionSUTID)
	for _, step := range snapshot.Steps {
		ids = append(ids, step.TargetVersionSUTID)
	}
	if len(ids) == 0 || (len(ids) == 1 && ids[0] <= 0) {
		ids = append(ids, snapshot.VersionSUTIDs...)
	}
	normalized, err := uniqueSortedIDs(ids)
	if err != nil {
		return append([]int64(nil), snapshot.VersionSUTIDs...)
	}
	return normalized
}
